INSERT INTO `books` (`id`, `category_id`, `title`, `author`, `publisher`, `publish_year`, `description`, `cover_image`, `quantity`, `available_copies`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Nhà Giả Kim (The Alchemist)', 'Paulo Coelho', 'NXB Trẻ', 2024, 'Hành trình vượt sa mạc đi tìm kho báu của chàng chăn cừu Santiago, gửi gắm triết lý sâu sắc: Khi bạn khao khát một điều gì, cả vũ trụ sẽ hợp lực giúp bạn đạt được.', 'https://covers.openlibrary.org/b/id/10543204-L.jpg', 14, 17, '2026-10-05 10:06:14', '2026-10-08 02:18:10'),
	(2, 1, 'Tội Ác và Hình Phạt', 'Fyodor Dostoevsky', 'NXB Trẻ', 2024, 'Kiệt tác tâm lý vĩ đại mổ xẻ cuộc giằng xé lương tâm và hành trình cứu rỗi tâm hồn của chàng cựu sinh viên nghèo Raskolnikov tại nước Nga thế kỷ 19.', 'https://covers.openlibrary.org/b/id/12833525-L.jpg', 6, 6, '2026-10-05 10:06:14', '2026-10-05 10:06:14'),
	(3, 1, 'Trăm Năm Cô Đơn', 'Gabriel García Márquez', 'NXB Trẻ', 2024, 'Đỉnh cao của chủ nghĩa hiện thực huyền ảo, kể về bảy thế hệ dòng họ Buendía tại ngôi làng Macondo huyền thoại, soi tỏ bản ngã cô đơn của con người.', 'https://covers.openlibrary.org/b/id/8231850-L.jpg', 5, 5, '2026-10-05 10:06:14', '2026-10-05 10:06:14'),
	(4, 1, 'Những Người Khốn Khổ (Les Misérables)', 'Victor Hugo', 'NXB Trẻ', 2024, 'Bản trường ca bất hủ về lòng bao dung, sự hy sinh và khát vọng tự do của Jean Valjean giữa những biến cố lịch sử khắc nghiệt của nước Pháp.', 'https://covers.openlibrary.org/b/id/12843515-L.jpg', 7, 7, '2026-10-05 10:06:14', '2026-10-05 12:08:16'),
	(5, 1, 'Ông Già Và Biển Cả', 'Ernest Hemingway', 'NXB Trẻ', 2024, 'Tác phẩm đoạt giải Nobel khẳng định phẩm giá và ý chí sắt đá của con người trước nghịch cảnh: Con người có thể bị hủy diệt nhưng không thể bị đánh bại.', 'https://covers.openlibrary.org/b/id/8231856-L.jpg', 9, 9, '2026-10-05 10:06:14', '2026-10-05 10:06:14'),
	(6, 1, 'Hoàng Tử Bé (The Little Prince)', 'Antoine de Saint-Exupéry', 'NXB Trẻ', 2024, 'Câu chuyện ngụ ngôn tuyệt mỹ về tình yêu, trách nhiệm và vẻ đẹp của sự giản đơn: Người ta chỉ thấy rõ bằng trái tim, điều cốt lõi vô hình trong mắt trần.', 'https://covers.openlibrary.org/b/id/8225261-L.jpg', 10, 10, '2026-10-05 10:06:14', '2026-10-05 12:08:16'),
	(7, 15, 'Đắc Nhân Tâm (How to Win Friends and Influence People)', 'Dale Carnegie', 'NXB Trẻ', 2024, 'Cuốn sách nghệ thuật giao tiếp kinh điển nhất mọi thời đại, hướng dẫn chân thành và thực tế để thấu hiểu, kết nối và cảm hóa lòng người.', 'https://covers.openlibrary.org/b/id/12547190-L.jpg', 12, 12, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(8, 15, 'Atomic Habits (Thói Quen Nguyên Tử)', 'James Clear', 'NXB Trẻ', 2024, 'Phương pháp khoa học xây dựng thói quen tốt và loại bỏ thói quen xấu, tạo ra bước nhảy vọt phi thường chỉ từ những thay đổi 1% mỗi ngày.', 'https://covers.openlibrary.org/b/id/12885917-L.jpg', 8, 8, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(9, 15, 'Tư Duy Nhanh Và Chậm (Thinking, Fast and Slow)', 'Daniel Kahneman', 'NXB Trẻ', 2024, 'Công trình đoạt giải Nobel Kinh tế giải mã hai hệ thống tư duy: Hệ thống 1 trực giác, bộc phát và Hệ thống 2 chậm rãi, logic nhưng lười biếng.', 'https://covers.openlibrary.org/b/id/8292885-L.jpg', 6, 6, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(10, 15, 'Đi Tìm Lẽ Sống (Man\'s Search for Meaning)', 'Viktor E. Frankl', 'NXB Trẻ', 2024, 'Trải nghiệm sinh tử trong trại tập trung Auschwitz và liệu pháp ý nghĩa: Người có một lý do để sống có thể chịu đựng hầu hết mọi nghịch cảnh.', 'https://covers.openlibrary.org/b/id/8231991-L.jpg', 7, 7, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(11, 26, 'Tâm Lý Học Về Tiền (The Psychology of Money)', 'Morgan Housel', 'Harriman House / NXB Công Thương', 2020, '19 câu chuyện sâu sắc lý giải cách con người tư duy và đưa ra quyết định với tiền bạc. Khẳng định thành công tài chính cá nhân không phụ thuộc vào chỉ số IQ hay công thức phức tạp mà quyết định bởi sự kiên nhẫn, khiêm tốn và kỷ luật hành vi. [Giá bìa: 175.000 VNĐ]', 'https://covers.openlibrary.org/b/isbn/9780857197689-L.jpg', 15, 15, '2026-10-05 10:06:14', '2026-10-08 03:21:15'),
	(18, 17, 'Lược Sử Thời Gian (A Brief History of Time)', 'Stephen Hawking', 'NXB Trẻ', 2024, 'Bức tranh toàn cảnh về nguồn gốc và số phận của vũ trụ, giải thích hố đen, thời gian và không gian dưới góc nhìn vật lý lý thuyết hiện đại.', 'https://covers.openlibrary.org/b/id/8301292-L.jpg', 7, 7, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(19, 17, 'Vũ Trụ (Cosmos)', 'Carl Sagan', 'NXB Trẻ', 2024, 'Hành trình tráng lệ khám phá 15 tỷ năm tiến hóa của vũ trụ và khoa học, khơi dậy niềm say mê tri thức và vị thế của con người trong đại dương ngân hà.', 'https://covers.openlibrary.org/b/id/10574880-L.jpg', 6, 6, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(20, 17, 'Vũ Trụ Trong Vỏ Hạt Dẻ (The Universe in a Nutshell)', 'Stephen Hawking', 'NXB Trẻ', 2024, 'Cuốn sách khám phá các biên giới kỳ thú nhất của vật lý hiện đại: Lý thuyết dây, không thời gian đa chiều và tương lai của loài người.', 'https://covers.openlibrary.org/b/id/8301292-L.jpg', 5, 5, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(21, 18, 'Sapiens: Lược Sử Loài Người', 'Yuval Noah Harari', 'NXB Trẻ', 2024, 'Cuốn sách lịch sử hiện tượng toàn cầu, truy vết hành trình của một loài vượn người vô danh vươn lên thống trị hành tinh nhờ năng lực tưởng tượng tập thể.', 'https://covers.openlibrary.org/b/id/8810703-L.jpg', 11, 11, '2026-10-05 10:06:14', '2026-10-05 18:53:32'),
	(22, 18, 'Homo Deus: Lược Sử Tương Lai', 'Yuval Noah Harari', 'NXB Trẻ', 2024, 'Tiếp nối Sapiens, cuốn sách vẽ nên tương lai của loài người khi công nghệ sinh học và trí tuệ nhân tạo đưa con người tiệm cận sức mạnh thần thánh.', 'https://covers.openlibrary.org/b/id/8810703-L.jpg', 8, 8, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(23, 19, 'Cộng Hòa (The Republic)', 'Plato', 'NXB Trẻ', 2024, 'Đối thoại triết học nền tảng của văn minh phương Tây, bàn về công lý, trật tự xã hội lý tưởng và câu chuyện ngụ ngôn nổi tiếng về cái hang.', 'https://covers.openlibrary.org/b/id/8231995-L.jpg', 5, 5, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(24, 16, 'Từ Tốt Đến Vĩ Đại (Good to Great)', 'Jim Collins', 'NXB Trẻ', 2024, 'Nghiên cứu công phu suốt nhiều thập kỷ giải mã lý do tại sao một số công ty tạo ra bước nhảy vọt phi thường trong khi các đối thủ khác dậm chân tại chỗ.', 'https://covers.openlibrary.org/b/id/8235114-L.jpg', 7, 7, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(25, 16, 'Zero to One (Từ Không Đến Một)', 'Peter Thiel, Blake Masters', 'NXB Trẻ', 2024, 'Tư duy khởi nghiệp công nghệ đột phá: Cách xây dựng các sản phẩm độc quyền sáng tạo thay vì sao chép và cạnh tranh theo lối mòn.', 'https://covers.openlibrary.org/b/id/8235114-L.jpg', 9, 9, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(26, 26, 'Khởi Nghiệp Tinh Gọn (The Lean Startup)', 'Eric Ries', 'Crown Business / NXB Tổng Hợp TP.HCM', 2011, 'Mô hình khởi nghiệp thực chiến với chu trình Xây dựng - Đo lường - Học hỏi (Build-Measure-Learn). Giúp doanh nhân và nhà sáng lập thử nghiệm sản phẩm khả dụng tối thiểu (MVP) với chi phí thấp nhất và thích ứng linh hoạt. [Giá bìa: 195.000 VNĐ]', 'https://covers.openlibrary.org/b/isbn/9780307887894-L.jpg', 11, 10, '2026-10-05 10:06:14', '2026-10-08 03:21:15'),
	(27, 16, 'Cha Giàu Cha Nghèo (Rich Dad Poor Dad)', 'Robert T. Kiyosaki', 'NXB Trẻ', 2024, 'Bài học vỡ lòng thay đổi hoàn toàn tư duy về tài sản, tiêu sản và giáo dục tài chính để chủ động đạt được tự do tài chính bền vững.', 'https://covers.openlibrary.org/b/id/12833530-L.jpg', 8, 8, '2026-10-05 10:06:14', '2026-10-05 12:17:05'),
	(28, 1, 'Tội Ác và Hình Phạt (Crime and Punishment)', 'Fyodor Dostoevsky', 'NXB Trẻ', 2024, 'Kiệt tác tâm lý vĩ đại mổ xẻ cuộc giằng xé lương tâm và hành trình cứu rỗi tâm hồn của chàng cựu sinh viên nghèo Raskolnikov tại nước Nga thế kỷ 19.', 'https://covers.openlibrary.org/b/id/12833525-L.jpg', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(29, 1, 'Trăm Năm Cô Đơn (One Hundred Years of Solitude)', 'Gabriel García Márquez', 'NXB Trẻ', 2024, 'Đỉnh cao của chủ nghĩa hiện thực huyền ảo, kể về bảy thế hệ dòng họ Buendía tại ngôi làng Macondo huyền thoại, soi tỏ bản ngã cô đơn của con người.', 'https://covers.openlibrary.org/b/id/8231850-L.jpg', 5, 5, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(30, 15, 'Thói Quen Nguyên Tử (Atomic Habits)', 'James Clear', 'NXB Trẻ', 2024, 'Phương pháp khoa học đột phá: Thay đổi 1% mỗi ngày để tạo nên bước nhảy vọt vĩ đại, giải mã quy trình 4 bước hình thành và duy trì thói quen bền vững.', 'https://covers.openlibrary.org/b/id/12885917-L.jpg', 8, 8, '2026-10-05 12:08:16', '2026-10-05 18:53:05'),
	(31, 15, '7 Thói Quen Của Người Thành Đạt (The 7 Habits of Highly Effective People)', 'Stephen R. Covey', 'NXB Trẻ', 2024, 'Hệ thống nguyên lý trường tồn rèn luyện tính chủ động, tư duy cùng thắng và rèn giũa bản thân để đạt hiệu quả tối ưu trong cuộc sống.', 'https://covers.openlibrary.org/b/id/9255566-L.jpg', 8, 8, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(32, 17, 'Vật Lý Thiên Văn Cho Người Vội Vã', 'Neil deGrasse Tyson', 'NXB Trẻ', 2024, 'Những khái niệm vật lý thiên văn cốt lõi được đúc kết ngắn gọn, dí dỏm, từ năng lượng tối, vật chất tối đến thuyết lượng tử trong lòng vũ trụ.', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?auto=format&fit=crop&w=600&q=80', 8, 8, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(40, 16, 'Từ Số 0 Đến Số 1 (Zero to One)', 'Peter Thiel & Blake Masters', 'NXB Trẻ', 2024, 'Bí quyết khởi nghiệp đột phá từ nhà sáng lập PayPal và nhà đầu tư đầu tiên của Facebook: Đừng cạnh tranh sao chép, hãy tạo ra giá trị độc quyền mới.', 'https://covers.openlibrary.org/b/id/8235114-L.jpg', 8, 8, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(41, 18, 'Súng, Vi Trùng và Thép (Guns, Germs, and Steel)', 'Jared Diamond', 'NXB Trẻ', 2024, 'Tác phẩm đoạt giải Pulitzer lý giải nguồn gốc sâu xa của sự bất bình đẳng xã hội loài người qua yếu tố địa lý, môi trường tự nhiên và thuần hóa sinh vật.', 'https://images.unsplash.com/photo-1505664194779-8beaceb93744?auto=format&fit=crop&w=600&q=80', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(42, 18, 'Con Đường Tơ Lụa (The Silk Roads)', 'Peter Frankopan', 'NXB Trẻ', 2024, 'Một thiên sử thi viết lại dòng chảy thương mại, tôn giáo và quyền lực toàn cầu dịch chuyển qua chiếc nôi Trung Á suốt hàng ngàn năm.', 'https://covers.openlibrary.org/b/id/12843515-L.jpg', 7, 7, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(43, 19, 'Suy Tưởng (Meditations)', 'Marcus Aurelius', 'NXB Trẻ', 2024, 'Những ghi chép tự vấn sâu kín của vị hoàng đế La Mã vĩ đại, đại diện tiêu biểu nhất cho Chủ nghĩa Khắc kỷ (Stoicism) về sự điềm tĩnh và kỷ luật nội tâm.', 'https://covers.openlibrary.org/b/id/8231995-L.jpg', 9, 9, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(44, 19, 'Zarathustra Đã Nói Như Thế (Thus Spoke Zarathustra)', 'Friedrich Nietzsche', 'NXB Trẻ', 2024, 'Tác phẩm triết học kinh điển đề xướng khái niệm Siêu nhân (Übermensch), ý chí hùng cường và lời kêu gọi vượt lên trên những giáo điều tầm thường.', 'https://images.unsplash.com/photo-1516979187457-637abb4f9353?auto=format&fit=crop&w=600&q=80', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(45, 19, 'Bàn Về Tự Do (On Liberty)', 'John Stuart Mill', 'NXB Trẻ', 2024, 'Khảo luận mẫu mực đặt nền móng cho tư tưởng tự do cá nhân, quyền tự do ngôn luận và giới hạn đạo đức của quyền lực nhà nước.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=600&q=80', 5, 5, '2026-10-05 12:08:16', '2026-10-05 12:17:05'),
	(46, 10, 'The Design of Everyday Things: Thiết Kế Đồ Vật Hàng Ngày', 'Don Norman', 'NXB Trẻ', 2024, 'Kinh thánh của ngành thiết kế trải nghiệm người dùng (UX), phân tích tâm lý nhận thức và cách tạo ra những sản phẩm thông minh, trực quan.', 'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&fit=crop&w=600&q=80', 7, 7, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(47, 10, 'Don\'t Make Me Think: Đừng Bắt Tôi Phải Suy Nghĩ', 'Steve Krug', 'NXB Trẻ', 2024, 'Cẩm nang thiết kế giao diện web thực dụng và dí dỏm nhất: Một giao diện thành công là giao diện người dùng hiểu ngay mà không cần dừng lại suy nghĩ.', 'https://covers.openlibrary.org/b/id/10543210-L.jpg', 8, 8, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(48, 10, 'Câu Chuyện Nghệ Thuật (The Story of Art)', 'E.H. Gombrich', 'NXB Trẻ', 2024, 'Cuốn sách lịch sử mỹ thuật nổi tiếng nhất thế giới, dẫn dắt độc giả qua từng thời kỳ từ hội họa hang động tiền sử đến nghệ thuật đương đại.', 'https://images.unsplash.com/photo-1581291518857-4e27b48ff24e?auto=format&fit=crop&w=600&q=80', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(49, 11, 'Tại Sao Chúng Ta Ngủ (Why We Sleep)', 'Matthew Walker', 'NXB Trẻ', 2024, 'Nghiên cứu khoa học đột phá của giáo sư thần kinh học giải mã sức mạnh phục hồi kỳ diệu của giấc ngủ đối với trí nhớ, tuổi thọ và sức khỏe tinh thần.', 'https://covers.openlibrary.org/b/id/8292885-L.jpg', 9, 9, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(50, 11, 'Hơi Thở: Khoa Học Mới Về Nghệ Thuật Bị Quên Lãng (Breath)', 'James Nestor', 'NXB Trẻ', 2024, 'Hành trình y khoa thực nghiệm chứng minh rằng cách chúng ta hít thở có thể đảo ngược nhiều căn bệnh mãn tính và phục hồi thể trạng đỉnh cao.', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?auto=format&fit=crop&w=600&q=80', 7, 7, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(51, 11, 'Bác Sĩ Tốt Nhất Là Chính Mình (Anticancer)', 'David Servan-Schreiber', 'NXB Trẻ', 2024, 'Phương pháp củng cố hệ miễn dịch tự nhiên, chế độ dinh dưỡng lành mạnh và lối sống thanh lọc tế bào dựa trên các bằng chứng y khoa hiện đại.', 'https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?auto=format&fit=crop&w=600&q=80', 8, 8, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(52, 12, 'Bộ Não Tự Chữa Lành (The Brain That Changes Itself)', 'Norman Doidge', 'NXB Trẻ', 2024, 'Cuộc cách mạng thần kinh học chứng minh não bộ con người có khả năng tái cấu trúc và chữa lành liên tục suốt cuộc đời thông qua tư duy.', 'https://images.unsplash.com/photo-1505751172876-fa1923c5c528?auto=format&fit=crop&w=600&q=80', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(53, 12, 'Kẻ Khác Trong Bạn (The Tell-Tale Brain)', 'V.S. Ramachandran', 'NXB Trẻ', 2024, 'Khám phá thế giới kỳ bí của tâm trí qua các ca bệnh thần kinh hiếm gặp, hé lộ nguồn gốc của ngôn ngữ, đồng cảm và sự sáng tạo của con người.', 'https://covers.openlibrary.org/b/id/8292885-L.jpg', 5, 5, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(54, 13, 'Mùa Xuân Vắng Lặng (Silent Spring)', 'Rachel Carson', 'NXB Trẻ', 2024, 'Cuốn sách chấn động khai sinh phong trào bảo vệ môi trường toàn cầu, cảnh báo nguy cơ hủy diệt hệ sinh thái do hóa chất độc hại.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=600&q=80', 6, 6, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(55, 13, 'Trái Đất Không Thể Sinh Sống (The Uninhabitable Earth)', 'David Wallace-Wells', 'NXB Trẻ', 2024, 'Bản báo cáo cảnh tỉnh sâu sắc về tương lai khí hậu Trái đất nếu nhân loại không hành động ngay hôm nay để bảo vệ hành tinh.', 'https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=600&q=80', 7, 7, '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(56, 1, 'Kiến Trúc Ông Già và Biển Cả', 'Robert C. Martin', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Văn học & Tiểu thuyết kinh điển, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231856-L.jpg', 0, 0, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(59, 14, 'Kỹ Thuật Dịch Ngược Mã Độc (Reverse Engineering) (Chiến Lược)', 'Erich Gamma', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề An toàn Thông tin & Hacker Mũ Trắng, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=600&q=80', 11, 11, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(60, 15, 'Bách Khoa Tâm Lý Học Đám Đông và Dư Luận', 'Linus Torvalds', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Tâm lý học & Phát triển Bản thân, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231991-L.jpg', 4, 4, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(61, 16, 'Xây Dựng Hệ Sinh Thái Khởi Nghiệp: Đột Phá và Thực Chiến', 'Stuart Russell', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Kinh tế số, Tài chính & Đầu tư, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=600&q=80', 13, 13, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(62, 17, 'Thực Chiến Lịch Sử Khám Phá Không Gian - Thế Kỷ 21', 'Peter Norvig', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Khoa học Vũ trụ & Vật lý Lượng tử, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?auto=format&fit=crop&w=600&q=80', 11, 11, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(63, 18, 'Khảo Cổ Học Ai Cập và Kim Tự Tháp (Thực Hành)', 'Ian Goodfellow', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Lịch sử Thế giới, Chiến lược & Quân sự, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231850-L.jpg', 14, 14, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(64, 19, 'Lược Sử Luận Đạo Giữa Cuộc Đời Biến Động', 'Aurélien Géron', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Triết học Đông Tây & Nhân sinh quan, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1516979187457-637abb4f9353?auto=format&fit=crop&w=600&q=80', 11, 11, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(65, 20, 'Đột Biến Di Truyền Thế Hệ Mới: Đột Phá và Thực Chiến', 'Donald Knuth', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Tiểu thuyết Cyberpunk, Khoa học Viễn tưởng (Sci-Fi), cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&w=600&q=80', 4, 4, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(66, 21, 'Phân Tích Chuyển Sinh Thành Dũng Sĩ Hư Cấu - Trong Kỷ Nguyên Số', 'Kevin Mitnick', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Truyện tranh Manga & Light Novel, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&w=600&q=80', 13, 13, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(67, 11, 'Liệu Pháp Vận Động Chữa Lành (Bản Đồ)', 'Bruce Schneier', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Y học, Sức khỏe & Dinh dưỡng, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?auto=format&fit=crop&w=600&q=80', 3, 3, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(68, 1, 'Cốt Lõi Tiếng Chim Hót Trong Bụi Mận Gai', 'Gene Kim', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Văn học & Tiểu thuyết kinh điển, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231850-L.jpg', 3, 3, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(71, 14, 'Tường Lửa và Hệ Thống IDS/IPS (Bản Đồ)', 'Stephen Hawking', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề An toàn Thông tin & Hacker Mũ Trắng, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=600&q=80', 3, 3, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(72, 15, 'Giải Mã Khai Sáng Tiềm Năng Vô Hạn', 'Carl Sagan', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Tâm lý học & Phát triển Bản thân, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231991-L.jpg', 15, 15, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(73, 16, 'Chiến Lược Đại Dương Xanh: Bỏ Túi', 'Neil deGrasse Tyson', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Kinh tế số, Tài chính & Đầu tư, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8235114-L.jpg', 13, 13, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(74, 17, 'Nguyên Lý Sóng Hấp Dẫn và Kính Thiên Văn James Webb - Chuyên Sâu', 'Richard Feynman', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Khoa học Vũ trụ & Vật lý Lượng tử, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/10574880-L.jpg', 15, 15, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(75, 18, 'Các Nền Văn Minh Cổ Đại Lưỡng Hà (Cốt Lõi)', 'Michio Kaku', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Lịch sử Thế giới, Chiến lược & Quân sự, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://covers.openlibrary.org/b/id/8231850-L.jpg', 8, 8, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(76, 19, 'Đột Phá Bản Thể Luận và Nhận Thức Luận', 'Yuval Noah Harari', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Triết học Đông Tây & Nhân sinh quan, cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1516979187457-637abb4f9353?auto=format&fit=crop&w=600&q=80', 0, 0, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(77, 20, 'Những Kẻ Sống Ngoài Vòng Mạng Lưới: Tập 1: Khởi Đầu', 'Jared Diamond', 'NXB Trẻ', 2024, 'Tác phẩm xuất sắc thuộc chủ đề Tiểu thuyết Cyberpunk, Khoa học Viễn tưởng (Sci-Fi), cung cấp kiến thức nền tảng vững chắc và định hướng tư duy ứng dụng sâu sắc dành cho độc giả yêu tri thức.', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&w=600&q=80', 10, 10, '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
