INSERT INTO `categories` (`id`, `name`, `description`, `created_at`, `updated_at`) VALUES
	(1, 'Văn học & Tiểu thuyết kinh điển', 'Các kiệt tác văn học kinh điển thế giới, phản ánh chiều sâu nhân sinh, tâm hồn và các giá trị nhân đạo trường tồn.', '2026-10-05 10:06:14', '2026-10-05 12:13:20'),
	(10, 'Nghệ thuật, Thiết kế & UI/UX', 'Tư duy thiết kế lấy người dùng làm trung tâm, tâm lý học thị giác, màu sắc và mỹ thuật đương đại.', '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(11, 'Y học, Sức khỏe & Dinh dưỡng', 'Khoa học về giấc ngủ, hô hấp, hệ miễn dịch tự nhiên, chế độ dinh dưỡng tối ưu và y học phòng ngừa trường thọ.', '2026-10-05 12:08:16', '2026-10-05 12:13:21'),
	(12, 'Khoa học thần kinh & Não bộ', 'Giải mã cấu trúc nơ-ron, tính mềm dẻo của não bộ (Neuroplasticity) và nguồn gốc của ý thức con người.', '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(13, 'Môi trường & Khoa học Trái đất', 'Hệ sinh thái toàn cầu, biến đổi khí hậu, phát triển bền vững và bảo vệ hành tinh xanh.', '2026-10-05 12:08:16', '2026-10-05 12:08:16'),
	(14, 'An toàn Thông tin & Hacker Mũ Trắng', 'Kỹ thuật kiểm thử xâm nhập (Penetration Testing), an ninh mạng thực chiến, mật mã học và phòng thủ không gian mạng.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(15, 'Tâm lý học & Phát triển Bản thân', 'Rèn luyện thói quen nguyên tử, tâm lý học hành vi, quản lý cảm xúc, tư duy tích cực và bứt phá giới hạn bản thân.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(16, 'Kinh tế số, Tài chính & Đầu tư', 'Tư duy tài chính thông minh, khởi nghiệp tinh gọn, phân tích thị trường chứng khoán và kinh tế học trong thời đại số.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(17, 'Khoa học Vũ trụ & Vật lý Lượng tử', 'Khám phá bí ẩn vụ nổ Big Bang, cơ học lượng tử, lỗ đen, thuyết tương đối và bức tranh kỳ vĩ của không thời gian.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(18, 'Lịch sử Thế giới, Chiến lược & Quân sự', 'Biến thiên các đế chế cổ đại, chiến lược quân sự kinh điển, các cuộc chiến tranh định hình thế giới và bài học lịch sử.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(19, 'Triết học Đông Tây & Nhân sinh quan', 'Tư tưởng Khắc kỷ (Stoicism), triết học Hy Lạp cổ đại, triết học phương Đông, Lão Trang và nghệ thuật sống ý nghĩa.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(20, 'Tiểu thuyết Cyberpunk, Khoa học Viễn tưởng (Sci-Fi)', 'Tương lai viễn tưởng công nghệ cao, thực tại ảo (Virtual Reality), người máy sinh học Cyborg và du hành liên sao.', '2026-10-05 12:13:20', '2026-10-05 12:13:20'),
	(21, 'Truyện tranh Manga & Light Novel', 'Kiệt tác truyện tranh Nhật Bản, tiểu thuyết phiêu lưu kỳ ảo, thế giới giả tưởng và hành trình vượt qua nghịch cảnh.', '2026-10-05 12:13:21', '2026-10-05 12:13:21'),
	(22, 'Trí tuệ nhân tạo (AI) & Khoa học Dữ liệu', 'Nghiên cứu mô hình học máy, học sâu, AI tạo sinh (Generative AI), mô hình ngôn ngữ lớn (LLM) và xử lý dữ liệu lớn.', '2026-10-05 12:17:34', '2026-10-05 12:17:34'),
	(23, 'Lập trình & Kỹ thuật Phần mềm', 'Kiến trúc hệ thống, mã sạch (Clean Code), mẫu thiết kế (Design Patterns), vi dịch vụ (Microservices) và DevOps hiện đại.', '2026-10-05 12:17:34', '2026-10-05 12:17:34'),
	(24, 'Nghệ thuật, Kiến trúc & Thiết kế', 'Lịch sử hội họa thế giới, tinh hoa kiến trúc cổ điển đến hiện đại, tư duy thẩm mỹ và nguyên lý thiết kế đồ họa.', '2026-10-07 10:05:40', '2026-10-07 10:05:40'),
	(25, 'Công Nghệ Thông Tin & Kỹ Thuật Phần Mềm', 'Kho tàng tri thức về kỹ thuật lập trình, kiến trúc hệ thống dữ liệu lớn, quy trình Agile/DevOps và ứng dụng Trí tuệ Nhân tạo thực chiến.', '2026-10-08 03:21:15', '2026-10-08 03:21:15'),
	(26, 'Kinh Tế, Tài Chính & Marketing', 'Tài liệu quản trị kinh doanh, đầu tư chứng khoán giá trị, khởi nghiệp đổi mới sáng tạo, tâm lý học hành vi tài chính và chiến lược marketing toàn cầu.', '2026-10-08 03:21:15', '2026-10-08 03:21:15'),
	(27, 'Y Tế & Chăm Sóc Sức Khỏe', 'Bộ sách y khoa chuẩn mực về giải phẫu học người, dược lý lâm sàng, kỹ năng kê đơn an toàn và lịch sử các phát kiến y học cứu rỗi nhân loại.', '2026-10-08 03:21:15', '2026-10-08 03:21:15'),
	(28, 'Thiết Kế Đồ Họa & Đa Phương Tiện', 'Tài liệu nền tảng về tư duy thiết kế lấy người dùng làm trung tâm (User-Centered Design), nghệ thuật bố cục thị giác, hệ thống màu sắc và Typography.', '2026-10-08 03:21:15', '2026-10-08 03:21:15'),
	(29, 'Xây Dựng & Kiến Trúc', 'Kho tàng kiến thức kỹ thuật kết cấu công trình dân dụng, cơ học vật liệu, quy hoạch không gian và lịch sử tiến hóa kiến trúc nhân loại.', '2026-10-08 03:21:15', '2026-10-08 03:21:15');
INSERT INTO `forum_categories` (`id`, `name`, `slug`, `icon`, `description`, `color`, `created_at`, `updated_at`) VALUES
	(1, 'Góc Review Sách', 'review-sach', '⭐', 'Cảm nhận, đánh giá và chia sẻ góc nhìn chân thực về các cuốn sách trong kho thư viện.', 'cyan', '2026-10-05 21:49:29', '2026-10-05 21:49:29'),
	(2, 'Hỏi Đáp & Tìm Sách', 'hoi-dap-tim-tai-lieu', '❓', 'Nơi độc giả đặt câu hỏi, tìm kiếm giáo trình, tài liệu chuyên ngành và nhờ thủ thư tư vấn.', 'amber', '2026-10-05 21:49:29', '2026-10-06 00:09:35'),
	(3, 'Luận Bàn Tri Thức', 'luan-ban-tri-thuc', '💬', 'Thảo luận sâu về triết học, khoa học công nghệ, kỹ năng phát triển bản thân và cuộc sống.', 'purple', '2026-10-05 21:49:29', '2026-10-05 21:49:29'),
	(4, 'Thông Báo Thư Viện', 'thong-bao-thu-vien', '📢', 'Cập nhật sách mới nhập kho, quy định mượn trả và các sự kiện giao lưu đặc biệt.', 'pink', '2026-10-05 21:49:29', '2026-10-05 21:49:29');
INSERT INTO `forum_comments` (`id`, `post_id`, `user_id`, `content`, `created_at`, `updated_at`) VALUES
	(1, 1, 1, 'Rất đồng tình với quan điểm của bạn! Cuốn này mình đọc 2 lần rồi vẫn thấy thấm.', '2026-10-05 21:49:29', '2026-10-05 21:49:29');
INSERT INTO `forum_posts` (`id`, `user_id`, `category_id`, `book_id`, `title`, `content`, `likes_count`, `views_count`, `is_pinned`, `created_at`, `updated_at`) VALUES
	(1, 1, 1, 1, 'Cảm nhận về cuốn sách "Nhà Giả Kim (The Alchemist)" - Đọc xong như được khai sáng!', 'Chào các đồng môn thư viện TIỂU ĐỘI 2P,\n\nHôm qua mình vừa hoàn thành cuốn sách này trong khu vực đọc sách Cyber Hub. Cuốn sách mang lại những góc nhìn cực kỳ sâu sắc về tư duy phát triển bản thân và hành trình chinh phục mục tiêu lớn.\n\nĐiểm mình thích nhất là lối hành văn súc tích, các ví dụ thực tiễn dễ áp dụng ngay vào đời sống học tập. Rất khuyến khích anh em mượn ngay về nghiền ngẫm!', 9, 67, 0, '2026-10-05 21:49:29', '2026-10-08 06:09:05'),
	(2, 1, 4, NULL, 'CHÀO MỪNG ĐỘC GIẢ ĐẾN VỚI "HỘI QUÁN TRI THỨC"', 'Kính gửi toàn thể độc giả và hội viên TIỂU ĐỘI 2P,\r\n\r\nPhân hệ Hội Quán Tri Thức chính thức khai mở để chúng ta cùng nhau chia sẻ những cuốn sách hay, đặt câu hỏi học thuật và giao lưu văn minh.\r\n\r\nLưu ý quan trọng:\r\n1. Diễn đàn hoàn toàn KHÔNG CỘNG EXP khi đăng bài/bình luận nhằm tránh spam bài rác.\r\n2. Vui lòng tôn trọng quan điểm cá nhân và sử dụng ngôn từ văn minh.\r\n3. Khi review sách, hãy nhớ chọn cuốn sách tương ứng trong thư viện để bạn đọc khác có thể mượn ngay bằng 1 click!\r\n\r\nChúc mọi người có những phút giây thư thái và bổ ích tại thư viện!', 16, 122, 1, '2026-10-05 21:49:29', '2026-10-08 03:33:53');
